const body = $input.first().json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0]) || {};
const value = change.value || {};
const phoneNumberId = (value.metadata && value.metadata.phone_number_id) || '';
const message = (value.messages && value.messages[0]) || null;
const from = message ? message.from : '';
const text = message && message.text && typeof message.text.body === 'string' ? message.text.body.trim() : '';
const errorCode = !phoneNumberId ? 'missing_phone_number_id' : (!message || !text ? 'not_a_text_message' : '');
return [{ json: { _error: errorCode, phoneNumberId, from, text } }];

const ctx = $input.first().json;
const businessName = ctx.businessName || 'nuestro negocio';
const prompts = Array.isArray(ctx.suggestedPrompts) ? ctx.suggestedPrompts : [];
const systemPrompt = [
  `Eres el asistente virtual de "${businessName}", respondiendo por WhatsApp.`,
  'Tu objetivo:',
  '1. Responder dudas del usuario con tono cercano y profesional, en espanol, de forma breve (maximo 60 palabras salvo que pidan mas detalle).',
  '2. Si detectas intencion de contacto (pedir cita, presupuesto, hablar con alguien, reservar), pide amablemente nombre y datos de contacto, y confirma que el equipo respondera pronto.',
  '3. NUNCA inventes precios, horarios, servicios ni datos concretos que no te hayan dado explicitamente -- si no lo sabes, dilo con honestidad y ofrece derivar a un humano.',
  prompts.length ? ('Temas frecuentes que este negocio espera que puedas ayudar a resolver: ' + prompts.join(', ') + '.') : '',
].filter(Boolean).join('\n');
return [{ json: { systemPrompt, businessName } }];

const llm = $input.first().json;
const ctx = $('Build System Prompt').first().json;
const input = $('Extract Input').first().json;
const msgLower = (input.text || '').toLowerCase();
const contactIntent = /(cita|presupuesto|contacto|llamar|llamame|reuni[oó]n|hablar|contratar|me interesa|quiero|necesito|reservar|agendar|disponibilidad|horario|email|correo|tel[eé]fono|whatsapp)/i.test(msgLower);
let reply = '';
let mode = 'llm';
let errorDetail = null;
if (llm && llm.choices && Array.isArray(llm.choices) && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content) {
  reply = llm.choices[0].message.content.toString().trim();
} else {
  mode = 'fallback';
  errorDetail = (llm && llm.error && llm.error.message) || 'unknown';
  reply = contactIntent
    ? ('Gracias por escribir. Para ayudarte mejor, cuentame tu nombre y un email o telefono de contacto -- alguien de ' + ctx.businessName + ' te respondera en breve.')
    : ('Gracias por tu mensaje. Ahora mismo no puedo darte una respuesta detallada, pero el equipo de ' + ctx.businessName + ' lo revisara. Si quieres, dejame tus datos de contacto.');
}
return [{ json: { phoneNumberId: input.phoneNumberId, from: input.from, text: input.text, reply, mode, contactIntent, error: errorDetail } }];

